-- 32 Mapmaker: paints terrains into an autotiled tilemap. Each cell holds a
-- terrain number (0 the sea, 1 sand, 2 grass, 3 rock); the coasts, beaches and
-- cliffs between them are the engine's (`autotile` on the map), redrawn the
-- frame a cell changes. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/32-mapmaker.scene"
local COLS, ROWS = 28, 16
local NAMES = { "sand", "grass", "rock" }
-- The brush ring takes the colour of what it paints (linear).
local TINT = {
    { 1.0, 0.85, 0.55 },
    { 0.45, 0.95, 0.35 },
    { 0.80, 0.78, 0.75 },
}

local post_on = nav.post_all_on(SCENE)
local captions = true
local map, brush, status
local terrain = 2
local size = 1
local seed = 32
local t = 0.0

local function refresh()
    if status then
        Text.set(status, "painting " .. NAMES[terrain] .. "   brush " .. size .. "x" .. size)
    end
    if brush then
        local c = TINT[terrain]
        Sprite.set_color(brush, c[1], c[2], c[3], 0.9)
        Transform.set_scale(brush, size, size)
    end
end

-- The same value noise as tools/gen_scenes.py's mm_noise, with Lua's own
-- random numbers for the lattice: a new island each R.
local lattice = {}
local function h(i, j)
    local k = i * 4096 + j
    local v = lattice[k]
    if v == nil then
        v = math.random()
        lattice[k] = v
    end
    return v
end

local function noise(x, y)
    local i, j = math.floor(x), math.floor(y)
    local fx, fy = x - i, y - j
    local sx, sy = fx * fx * (3 - 2 * fx), fy * fy * (3 - 2 * fy)
    local a = h(i, j) + (h(i + 1, j) - h(i, j)) * sx
    local b = h(i, j + 1) + (h(i + 1, j + 1) - h(i, j + 1)) * sx
    return a + (b - a) * sy
end

local function new_island()
    seed = seed + 1
    math.randomseed(seed)
    lattice = {}
    for y = 0, ROWS - 1 do
        for x = 0, COLS - 1 do
            local u = (x + 0.5) / COLS * 2 - 1
            local v = (y + 0.5) / ROWS * 2 - 1
            local d = math.sqrt((u * 1.05) ^ 2 + (v * 1.15) ^ 2)
            local n = noise(x / 5.0, y / 5.0) * 0.6 + noise(x / 2.5 + 50, y / 2.5 + 50) * 0.4
            local hgt = 1.0 - d * 1.15 + (n - 0.5) * 0.7
            local c = 3
            if hgt < 0.22 then c = 0 elseif hgt < 0.36 then c = 1 elseif hgt < 0.66 then c = 2 end
            Tilemap.set_tile(map, "ground", x, y, c)
        end
    end
end

local function paint(wx, wy, value)
    local tx, ty = Tilemap.world_to_tile(map, wx, wy)
    if tx == nil then return end
    -- A brush of n paints the n x n cells nearest the pointer.
    local lo = -math.floor((size - 1) / 2)
    for oy = lo, lo + size - 1 do
        for ox = lo, lo + size - 1 do
            local x, y = tx + ox, ty + oy
            if x >= 0 and y >= 0 and x < COLS and y < ROWS
                and Tilemap.get_tile(map, "ground", x, y) ~= value then
                Tilemap.set_tile(map, "ground", x, y, value)
            end
        end
    end
end

function init(entity)
    map = Entity.find_by_name("Map")
    brush = Entity.find_by_name("Brush")
    status = Entity.find_by_name("Status")
    refresh()
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_captions(captions) end
    if map == nil then return end

    local step = 0
    local wheel = tonumber(Input.get_mouse_wheel()) or 0
    if wheel > 0 or Input.is_key_just_pressed("E") then step = 1 end
    if wheel < 0 or Input.is_key_just_pressed("Q") then step = -1 end
    if step ~= 0 then
        terrain = (terrain - 1 + step) % #NAMES + 1
        refresh()
    end
    if Input.is_key_just_pressed("Space") then
        size = size == 1 and 2 or size == 2 and 3 or 1
        refresh()
    end
    if Input.is_key_just_pressed("R") then new_island() end

    local wx, wy = Input.get_mouse_world_position()
    if Input.is_mouse_left_pressed() then
        paint(wx, wy, terrain)
    elseif Input.is_mouse_right_pressed() then
        paint(wx, wy, 0)
    end

    -- The ring sits on the cells it would paint, and breathes.
    if brush then
        local tx, ty = Tilemap.world_to_tile(map, wx, wy)
        if tx ~= nil then
            local lo = -math.floor((size - 1) / 2)
            local cx = tx + lo + (size - 1) / 2
            local cy = ty + lo + (size - 1) / 2
            local x0, y0 = Tilemap.tile_to_world(map, 0, 0)
            local x1, y1 = Tilemap.tile_to_world(map, 1, 1)
            Transform.set_position(brush, x0 + (x1 - x0) * cx, y0 + (y1 - y0) * cy)
        end
        t = t + dt
        local k = size * (1.0 + 0.05 * math.sin(t * 4.0))
        Transform.set_scale(brush, k, k)
    end
end
